// server.mjs
// خادم عروض الأسعار — وحدات Node المدمجة فقط (http / fs / path / url) على المنفذ 3000
//   POST /api/quote : تحقق صارم من المدخلات + حساب المجاميع
//   GET  /          : تقديم index.html (واجهة عربية RTL)
// لا تخزين ولا خدمات خارجية.

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const HOST = '0.0.0.0';
const PORT = 3000;
const BODY_LIMIT_BYTES = 1024 * 1024; // حد حجم جسم الطلب: 1MB

/* ------------------------- استجابات JSON ------------------------- */

function sendJson(res, status, payload, extraHeaders = {}) {
  const body = Buffer.from(JSON.stringify(payload), 'utf8');
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': body.length,
    'Cache-Control': 'no-store',
    ...extraHeaders,
  });
  res.end(body);
}

/* ------------------------- تحقق صارم -------------------------
   لا تحويل للنصوص أو null إلى أرقام:
   يجب أن يكون النوع number صحيحًا (Integer) آمنًا (Safe) داخل المدى المطلوب.
------------------------------------------------------------------ */

function isIntInRange(value, min, max) {
  return (
    typeof value === 'number' &&
    Number.isInteger(value) &&
    Number.isSafeInteger(value) &&
    value >= min &&
    value <= max
  );
}

/* ------------------------- منطق التسعير ------------------------- */

function computeQuote(payload) {
  // الجسم يجب أن يكون كائنًا (وليس مصفوفة أو null أو قيمة أولية)
  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) return null;

  const { items, discountPercent, shippingCents } = payload;

  // items: مصفوفة من 1 إلى 100 عنصرًا
  if (!Array.isArray(items) || items.length < 1 || items.length > 100) return null;

  const seenSkus = new Set();
  let subtotalCents = 0;

  for (const item of items) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) return null;

    const { sku, unitPriceCents, quantity } = item;

    // sku: نص غير فارغ بعد trim ولا يتكرر داخل الطلب
    if (typeof sku !== 'string') return null;
    const trimmedSku = sku.trim();
    if (trimmedSku.length === 0) return null;
    if (seenSkus.has(trimmedSku)) return null;
    seenSkus.add(trimmedSku);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isIntInRange(unitPriceCents, 0, 10000000)) return null;
    // quantity: عدد صحيح من 1 إلى 10000
    if (!isIntInRange(quantity, 1, 10000)) return null;

    subtotalCents += unitPriceCents * quantity;
  }

  // discountPercent: عدد صحيح من 0 إلى 100
  if (!isIntInRange(discountPercent, 0, 100)) return null;
  // shippingCents: عدد صحيح من 0 إلى 1000000
  if (!isIntInRange(shippingCents, 0, 1000000)) return null;

  // سقف مجموع الأسعار قبل الخصم: 1000000000 سنت
  if (subtotalCents > 1000000000) return null;

  // discountCents = تقريب subtotalCents*discountPercent/100 إلى أقرب سنت
  // مع تقريب النصف للأعلى (مكافئ رياضيًا لـ Math.floor(x + 0.5)
  // لكن بعمليات صحيحة دقيقة بلا أخطاء الفاصلة العائمة)
  const discountCents = Math.floor((subtotalCents * discountPercent + 50) / 100);

  // الشحن يُضاف بعد الخصم ولا يدخل في حساب الخصم
  const totalCents = subtotalCents - discountCents + shippingCents;

  // الرد الناجح يحتوي هذه الحقول الأربعة فقط
  return { subtotalCents, discountCents, shippingCents, totalCents };
}

/* ------------------------- قراءة جسم الطلب ------------------------- */

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let received = 0;
    req.on('data', (chunk) => {
      received += chunk.length;
      if (received > BODY_LIMIT_BYTES) {
        reject(new Error('body_too_large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

/* ------------------------- الملفات الثابتة ------------------------- */

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

function serveStatic(res, requestPath) {
  let decoded;
  try {
    decoded = decodeURIComponent(requestPath);
  } catch {
    res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Bad Request');
    return;
  }
  if (decoded === '/' || decoded === '') decoded = '/index.html';

  // منع تجاوز المسار (path traversal)
  const filePath = path.normalize(path.join(__dirname, decoded));
  if (filePath !== __dirname && !filePath.startsWith(__dirname + path.sep)) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Forbidden');
    return;
  }

  fs.stat(filePath, (err, stat) => {
    if (err || !stat.isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('404 Not Found');
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
      'Content-Length': stat.size,
      'Cache-Control': 'no-cache',
    });
    // ملاحظة: Node يمنع إرسال الجسم تلقائيًا لطلبات HEAD
    fs.createReadStream(filePath).pipe(res);
  });
}

/* ------------------------- الخادم ------------------------- */

const server = http.createServer(async (req, res) => {
  const urlPath = (req.url || '/').split('?')[0];

  try {
    if (urlPath === '/api/quote') {
      if (req.method !== 'POST') {
        sendJson(res, 405, { error: 'invalid' }, { Allow: 'POST' });
        return;
      }

      let raw;
      try {
        raw = await readBody(req);
      } catch {
        // جسم أكبر من الحد المسموح أو خطأ في القراءة
        sendJson(res, 400, { error: 'invalid' });
        return;
      }

      let parsed;
      try {
        parsed = JSON.parse(raw.toString('utf8'));
      } catch {
        // JSON معطوب
        sendJson(res, 400, { error: 'invalid' });
        return;
      }

      const result = computeQuote(parsed);
      if (result === null) {
        // مدخلات مخالفة
        sendJson(res, 400, { error: 'invalid' });
        return;
      }

      // نجاح: 200 مع الحقول الأربعة فقط
      sendJson(res, 200, result);
      return;
    }

    if (req.method === 'GET' || req.method === 'HEAD') {
      serveStatic(res, urlPath);
      return;
    }

    res.writeHead(405, { Allow: 'GET, HEAD, POST', 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Method Not Allowed');
  } catch {
    // أي خطأ غير متوقع في المسار يُرجع 400 بصيغة موحدة
    if (!res.headersSent) sendJson(res, 400, { error: 'invalid' });
    else res.end();
  }
});

// منع انهيار الخادم عند طلبات HTTP مشوهة
server.on('clientError', (err, socket) => {
  if (socket.writable) {
    socket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
  }
});

server.listen(PORT, HOST, () => {
  console.log(`Quote server running at http://localhost:${PORT}/`);
});

server.on('error', (err) => {
  console.error('Server error:', err);
  process.exitCode = 1;
});

